-- Mardum Waypoint Paths

DELETE FROM `waypoint_path` WHERE `PathId` IN (9474400);
DELETE FROM `waypoint_path_node` WHERE `PathId` IN (9474400);


-- Wing lanes: node-for-node copies of 9474400 offset by each wingman's spawn delta vs the
-- leader (formation-follow drifts on aerial paths - parallel paths keep the triangle rigid).
-- MoveType/Flags/Velocity must stay in sync with the leader path row above.
DELETE FROM `waypoint_path` WHERE `PathId` IN (9474401, 9474402);

DELETE FROM `waypoint_path_node` WHERE `PathId` IN (9474401, 9474402);
SELECT 9474401, NodeId, PositionX + 7.228, PositionY - 0.881, PositionZ - 0.958, Orientation
FROM `waypoint_path_node` WHERE `PathId` = 9474400;

SELECT 9474402, NodeId, PositionX + 6.487, PositionY - 9.206, PositionZ + 0.001, Orientation
FROM `waypoint_path_node` WHERE `PathId` = 9474400;

